import * as THREE from "three";

/** The surface maps the renderer can wear. They are generated by
 * `pnpm assets:textures` and served from `public/art`. */
export interface ArtTextures {
  concrete: THREE.Texture | null;
  asphalt: THREE.Texture | null;
  grass: THREE.Texture | null;
  rust: THREE.Texture | null;
  /** Flipbook of the impact burst, packed by `tools/make-spark-atlas.ts`. */
  spark_atlas: THREE.Texture | null;
  /** Muzzle flash strip, packed by `tools/make-flipbook-atlas.ts`. */
  muzzle_atlas: THREE.Texture | null;
  /** Infected strike strip, packed by `tools/make-flipbook-atlas.ts`. */
  melee_atlas: THREE.Texture | null;
  /** Gunfire noise ring sheet, packed by `tools/make-flipbook-atlas.ts`. */
  noise_atlas: THREE.Texture | null;
  /** Death cloud sheet, packed by `tools/make-flipbook-atlas.ts`. */
  death_atlas: THREE.Texture | null;
  /** Structure collapse sheet, packed by `tools/make-flipbook-atlas.ts`. */
  collapse_atlas: THREE.Texture | null;
  /** Facade modules baked by `tools/blender/facades.py`: colour and lit-window mask per style. */
  facade_residential: THREE.Texture | null;
  facade_office: THREE.Texture | null;
  facade_industrial: THREE.Texture | null;
  facade_storefront: THREE.Texture | null;
  facade_residential_lit: THREE.Texture | null;
  facade_office_lit: THREE.Texture | null;
  facade_industrial_lit: THREE.Texture | null;
  facade_storefront_lit: THREE.Texture | null;
  /** Flat roof seen from above, from the same bake. */
  roof: THREE.Texture | null;
  /** Concrete sidewalk slabs seen from above, a 6.4 m module. */
  sidewalk: THREE.Texture | null;
  /** A double door in its surround, 2.4 by 3.2 m. */
  door: THREE.Texture | null;
  /** Construction dust sheet, packed by `tools/make-flipbook-atlas.ts`. */
  dust_atlas: THREE.Texture | null;
}

export type ArtName = keyof ArtTextures;

const NAMES: ArtName[] = [
  "concrete",
  "asphalt",
  "grass",
  "rust",
  "spark_atlas",
  "muzzle_atlas",
  "melee_atlas",
  "noise_atlas",
  "death_atlas",
  "dust_atlas",
  "collapse_atlas",
  "facade_residential",
  "facade_office",
  "facade_industrial",
  "facade_storefront",
  "facade_residential_lit",
  "facade_office_lit",
  "facade_industrial_lit",
  "facade_storefront_lit",
  "roof",
  "sidewalk",
  "door",
];

/** Photographic bakes ship as JPEG (no alpha, a quarter of the PNG size). */
const JPEG = new Set<ArtName>([
  "facade_residential",
  "facade_office",
  "facade_industrial",
  "facade_storefront",
  "facade_residential_lit",
  "facade_office_lit",
  "facade_industrial_lit",
  "facade_storefront_lit",
  "roof",
  "sidewalk",
  "door",
]);

/**
 * Loads the surface maps without blocking the first frame: the materials are
 * built with flat colours and gain their map as each file arrives. A missing
 * file keeps the flat colour, so art is never a hard dependency of booting.
 */
export function loadArtTextures(baseUrl: string, onReady: (art: ArtTextures) => void): ArtTextures {
  const art: ArtTextures = {
    concrete: null,
    asphalt: null,
    grass: null,
    rust: null,
    spark_atlas: null,
    muzzle_atlas: null,
    melee_atlas: null,
    noise_atlas: null,
    death_atlas: null,
    dust_atlas: null,
    collapse_atlas: null,
    facade_residential: null,
    facade_office: null,
    facade_industrial: null,
    facade_storefront: null,
    facade_residential_lit: null,
    facade_office_lit: null,
    facade_industrial_lit: null,
    facade_storefront_lit: null,
    roof: null,
    sidewalk: null,
    door: null,
  };
  const loader = new THREE.TextureLoader();
  for (const name of NAMES) {
    loader.load(
      `${baseUrl}art/${name}.${JPEG.has(name) ? "jpg" : "png"}`,
      (tex) => {
        tex.wrapS = tex.wrapT = THREE.RepeatWrapping;
        tex.colorSpace = THREE.SRGBColorSpace;
        tex.anisotropy = 4;
        tex.needsUpdate = true;
        art[name] = tex;
        onReady(art);
      },
      undefined,
      () => {
        art[name] = null;
      },
    );
  }
  return art;
}
